package com.fathom.transaction;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc class TransactionControllerIntegrationTest { @Autowired MockMvc mockMvc;
@Test void createAndList() throws Exception { String user=mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"T\",\"email\":\"t@a.com\",\"status\":\"ACTIVE\"}" )).andReturn().getResponse().getContentAsString(); String userId=user.split("\"id\":\"")[1].split("\"")[0]; String acc=mockMvc.perform(post("/api/users/"+userId+"/accounts").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"ICICI\",\"accountType\":\"BANK_ACCOUNT\"}" )).andReturn().getResponse().getContentAsString(); String accId=acc.split("\"id\":\"")[1].split("\"")[0]; mockMvc.perform(post("/api/users/"+userId+"/transactions").contentType(MediaType.APPLICATION_JSON).content("{\"accountId\":\""+accId+"\",\"transactionDate\":\"2026-05-01\",\"amount\":100.50,\"direction\":\"DEBIT\",\"transactionType\":\"EXPENSE\",\"source\":\"MANUAL\"}" )).andExpect(status().isOk()); mockMvc.perform(get("/api/users/"+userId+"/transactions")).andExpect(status().isOk()).andExpect(jsonPath("$[0].amount").value(100.50)); }}
